                proc = subprocess.Popen(["sh", "-c", "LANG=C top -bn1 | grep 'Cpu' || LANG=C top -bn1 | grep 'Cpu(s)'"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
