import subprocess
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    exe_name = f'python{python_version}'
    try:
        result = subprocess.check_output(
            [exe_name, '-c', 'import sys; print(sys.version)'],
            stderr=subprocess.STDOUT
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f'Failed to switch to Python {python_version}: {e.output.decode("utf-8", "ignore")}') from e
    except FileNotFoundError as e:
        raise RuntimeError(f'Python executable for version {python_version} not found') from e
    version_str = result.decode('utf-8').strip()
    if path_to_append not in sys.path:
        sys.path.append(path_to_append)
    return version_str

import subprocess
import os
import glob
# Constants
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    os.makedirs(ARCHIVE_DIR, exist_ok=True)
    files = glob.glob(pattern)
    if not files:
        raise FileNotFoundError("No files match the given pattern")
    base_name = os.path.basename(pattern)
    if not base_name or base_name in ("*", "?.*"):
        archive_name = "archive.tar.gz"
    else:
        archive_name = base_name.replace("*", "STAR").replace("?", "Q") + ".tar.gz"
    archive_path = os.path.join(ARCHIVE_DIR, archive_name)
    cmd = ["tar", "-czf", archive_path] + files
    result = subprocess.run(cmd)
    if result.returncode != 0:
        raise OSError("Failed to create archive")
    for f in files:
        try:
            os.remove(f)
        except FileNotFoundError:
            continue
    return archive_path

import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR, exist_ok=True)
    files = glob.glob(pattern)
    archive_name = 'archive.tar.gz'
    archive_path = os.path.join(ARCHIVE_DIR, archive_name)
    if files:
        cmd = ['tar', '-czf', archive_path]
        cmd.extend(files)
        try:
            subprocess.check_call(cmd)
        except Exception:
            return archive_path
        for f in files:
            try:
                os.remove(f)
            except Exception:
                pass
    else:
        open(archive_path, 'a').close()
    return archive_path
